#include <stdio.h>

int main(void) {
    int found = 0;
    for (int row = 1; row <= 3; row++) {
        for (int col = 1; col <= 3; col++) {
            if (row == 2 && col == 2) {
                printf("Found it!\n");
                found = 1;
                break;
            }
            printf("(%d,%d) ", row, col);
        }
        if (found) {
            break;
        }
    }
    printf("\nSearch finished.\n");
    return 0;
}

