#include <stdio.h>

int main(void) {
    int num;

    for (int i = 1; i <= 5; i++) {
        printf("Enter number %d (0 to stop): ", i);
        scanf("%d", &num);

        if (num == 0) {
            printf("Stopping early.\n");
            break;
        }
        if (num < 0) {
            printf("Negative, skipped.\n");
            continue;
        }
        printf("Square = %d\n", num * num);
    }

    printf("Loop over.\n");
    return 0;
}

#include <stdio.h>

int main(void) {
    for (int i = 1; i <= 20; i++) {
        if (i % 3 == 0) {
            continue;
        }
        printf("%d ", i);
    }
    printf("\n");
    return 0;
}
